                    ['question' => 'How many syllables are in the word "butterfly"?', 'options' => [['text' => '2', 'correct' => false], ['text' => '3', 'correct' => true], ['text' => '4', 'correct' => false], ['text' => '1', 'correct' => false]], 'explanation' => '"But-ter-fly" has three syllables, each a distinct beat you can clap out.'],
                    ['question' => 'What is the best instructional sequence for introducing phonological skills?', 'options' => [['text' => 'Phonemes, then syllables, then rhyme', 'correct' => false], ['text' => 'Rhyme and syllables, then onset-rime, then phonemes', 'correct' => true], ['text' => 'All skills taught simultaneously with no sequence', 'correct' => false], ['text' => 'Phonemes first because they matter most for reading', 'correct' => false]], 'explanation' => 'Phonological awareness develops from larger, easier units (words, syllables, rhyme) toward smaller, harder units (onset-rime, then individual phonemes), and instruction should follow that same progression.'],
