[
    'title' => 'Classroom Strategies for English Language Learners',
    'audience' => 'teachers',
    'level' => 'beginner',
    'short_desc' => 'Core strategies for making grade-level content accessible to English language learners through comprehensible input, scaffolding, and awareness of language proficiency levels.',
    'outcomes' => [
        'Apply comprehensible input techniques to make instruction accessible without watering down content',
